  "Reciprocity": {"Explanation": "The email offers a summary of recent conversations and provides information about Cuba, which may be seen as a reciprocal favor to the recipient."},
  "Scarcity": {"Explanation": "The email mentions the limited number of responses to a previous query, creating a sense of urgency."},
  "Authority": {"Explanation": "The email references a university and a conference, which may lend credibility to the information provided."},
  "Commitment/Consistency": {"Explanation": "The email references prior behavior, such as the recipient's previous email and the shared experiences of others, to encourage further action."},
  "Liking": {"Explanation": "The email uses familiarity and personalization to build rapport, such as referring to the recipient by name and mentioning shared experiences."},
  "Social proof": {"Explanation": "The email references the participation of others, such as the responses from four people and the shared experience of academics, to create a sense of social proof."}
}

